// Evaluate failures
// Reads the newest executions of the failed workflow (n8n API, newest
// first) and decides:
//   stop   the last `threshold` runs all failed -> deactivate the workflow
//          and e-mail, unless this streak was already e-mailed ("Earlier
//          alert for this streak?" checks workflow_failure_alerts)
// A successful run in between starts the count again. Runs still in
// flight after the stop find the earlier alert and send nothing.
// Mode: Run Once for All Items.

const ev = $('Error Trigger').first().json;
const cfg = $('Guard settings').first().json;
const res = $json; // full HTTP response of "Recent executions"

const threshold = Math.max(2, Number(cfg.threshold) || 10);
const wf = ev.workflow || {};
const exec = ev.execution || {};
const err = exec.error || ev.trigger?.error || {};

if (res.statusCode !== 200 || !Array.isArray(res.body?.data)) {
  // Never guess: without the history the guard cannot count. The run of
  // this workflow fails, so the problem shows up in n8n's execution list.
  const detail = res.statusCode === 401
    ? 'n8n API rejected the key - run playbook 06.3 (06_3_n8n_api_key.yml).'
    : `HTTP ${res.statusCode ?? '?'} ${String(res.body?.message || res.error?.message || '').slice(0, 200)}`;
  throw new Error(`Failure Guard cannot read the executions of "${wf.name}": ${detail}`);
}

const runs = res.body.data
  .filter((r) => r.finished !== false || r.status) // ignore runs still in progress
  .sort((a, b) => Number(b.id) - Number(a.id));
const failed = (r) => ['error', 'crashed'].includes(r.status);
let streak = 0;
while (streak < runs.length && failed(runs[streak])) streak++;

const stop = streak >= threshold;
const firstFailure = streak ? runs[streak - 1].startedAt : null;

return [{
  json: {
    stop,
    threshold,
    streak,
    workflow_id: String(wf.id || ''),
    workflow_name: wf.name || '(unknown workflow)',
    execution_id: exec.id ? String(exec.id) : null,
    execution_url: exec.url || null,
    error_node: err.node?.name || exec.lastNodeExecuted || null,
    error_message: String(err.message || err.description || 'no error message').slice(0, 1000),
    first_failure: firstFailure,
    last_failure: streak ? runs[0].startedAt : null,
  },
}];

// Build e-mail
// One e-mail per streak: what stopped, since when, the last error and how
// to restart it.
// Mode: Run Once for All Items.

const r = $('Evaluate failures').first().json;
const cfg = $('Guard settings').first().json;
const deact = $('Deactivate workflow').first().json;
const deactivated = deact.statusCode === 200;

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const when = (t) => (t ? new Date(t).toLocaleString('pl-PL', { timeZone: 'Europe/Warsaw' }) : '-');

const state = deactivated
  ? 'The workflow has been <b>deactivated</b>.'
  : `<b>Deactivation failed</b> (n8n API HTTP ${esc(deact.statusCode ?? '?')}) - the workflow is still active, deactivate it by hand.`;

const html = `
<p>${state} Its last <b>${r.streak}</b> runs failed (Failure Guard threshold: ${r.threshold}).</p>
<table cellpadding="4" style="border-collapse:collapse">
  <tr><td><b>Workflow</b></td><td>${esc(r.workflow_name)} (${esc(r.workflow_id)})</td></tr>
  <tr><td><b>First failure</b></td><td>${esc(when(r.first_failure))}</td></tr>
  <tr><td><b>Last failure</b></td><td>${esc(when(r.last_failure))}</td></tr>
  <tr><td><b>Failed node</b></td><td>${esc(r.error_node || '-')}</td></tr>
  <tr><td><b>Error</b></td><td><code>${esc(r.error_message)}</code></td></tr>
  ${r.execution_url ? `<tr><td><b>Execution</b></td><td><a href="${esc(r.execution_url)}">${esc(r.execution_url)}</a></td></tr>` : ''}
</table>
<p>To restart: fix the cause (for example unseal Vault or bring back the network), then activate the workflow again in n8n.
No further e-mail is sent for this streak.</p>`;

return [{
  json: {
    from: cfg.email_from,
    to: cfg.email_to || cfg.email_from,
    subject: `Cyber Sentinel: "${r.workflow_name}" ${deactivated ? 'stopped' : 'failing'} after ${r.streak} failed runs`,
    html,
    log: {
      workflow_id: r.workflow_id,
      workflow_name: r.workflow_name,
      execution_id: r.execution_id,
      failures: r.streak,
      first_failure: r.first_failure,
      error_node: r.error_node,
      error_message: r.error_message,
      deactivated,
      message: deactivated ? 'deactivated' : `deactivation failed: HTTP ${deact.statusCode ?? '?'}`,
    },
  },
}];
